Proof.
ltac2:(KReplay.run1 (kr_t_SegStrlen ()) ["FPX_0"] "h01rh14regsp;1p;2p;3g0000j10Tg000Uj16Tg001:j12Tg001Xj11Tg002;j25Tg002gj34Tg003>j23Tg004N#0R0#6#2R1%00#0#0#0#0#2#1'5%11R1f0R0g0053541W0/30W1o"). Qed.
Lemma sl_agree_trans : forall r1 r2 r3, sl_agree r1 r2 -> sl_agree r2 r3 -> sl_agree r1 r3.
Proof.
ltac2:(KReplay.run1 (kr_t_SegStrlen ()) ["FPX_0"] "h01rh12r1h22r2h32r3p;1p;2p;3p;4g0000j10Tg000Uj16Tg001:j12Tg001Xj11Tg002;j25Tg002gj34Tg006?j43Tg004N#0R0#6#2R1%00#0#0#0#0#2#1'5R0%11R1f0R2g0053541W0f2f1P2C3X30X20W1o"). Qed.
Lemma sl_agree_upd : forall regs regs' (rd : reg) v,
  sl_agree regs regs' -> In rd sl_clob -> sl_agree regs (regupd regs' rd v).
Proof.
ltac2:(KReplay.run1 (kr_t_SegStrlen ()) ["FPX_0"] "h01Hh13Hinh21rh32rdh44regsh55regs'h61vp;1p;2p;3p;7g0000j10Tg000Uj17Tg001:j13Tg001Xj11Tg002;j26Tg007Pj25Tg002gj32Tg008]j74Tg004N#0R0#7#3R1%00#0#0#0#0#3#1R0'6R2%11R1f3R3f2R4'5g0053R59214f0R6=215X21f5f4P3P4P6f1F4W1W0X60W3X52W4o"). Qed.
Lemma sl_agree_getr : forall regs regs' (r : reg), sl_agree regs regs' -> ~ In r sl_clob -> getr regs' r = getr regs r.
Proof.
ltac2:(KReplay.run1 (kr_t_SegStrlen ()) ["FPX_0"] "h01Hh12Hnh21rh34regsh45regs'p;1p;2p;3g0000j10Tg000Uj17Tg001:j12Tg001Xj11Tg002;j26Tg007Pj25Tg002gj34Tg009lj13Tg004N#0R0#7#2R1%00#0#0#0#0#2#1'6R0%11R1f2R2f1R3'5g00539413#3P3P2f0O2W1W0W2X40W3o"). Qed.
End FPX_0.
Ltac in_sl_clob := cbn [sl_clob In]; repeat first [ left; reflexivity | right ].
Ltac solve_sl_agree :=
  repeat (apply sl_agree_upd; [| in_sl_clob]); first [apply sl_agree_refl | assumption].

