  Lemma strlen_run : forall regs (ret : word),
    ret_ok ret -> getr regs 1 = ret -> getr regs 10 = s ->
    exists regs',
      msteps RSEGS (mkst regs (0xacef0 : word) mem rom) (mkst regs' ret mem rom)
